    refs.append(dict(claim_id=PID+'/T3.3',target='Steps(9)–(12), preliminary block selection/mean, Condition3.1 and d_star(20)',reference_kind='definition_reference',note='Separate the generic variance choice from estimator(8), and the actual estimated-gap algorithm from oracle(21).'))
    for n,sec in [('3.1','A.1'),('3.2','A.2'),('3.3','A.3')]:refs.append(dict(claim_id=PID+'/T'+n,target='Supplementary Section '+sec,reference_kind='proof_only',note='All appendix bodies are excluded; source extraction does not certify the deferred proof.'))
    refs.append(dict(claim_id=PID+'/T3.3',target='Lemma A.5, KMT coupling(19), oracle estimator(21)',reference_kind='proof_only',note='These justify or interpret the result; they do not replace its original algorithm or become extra assumptions.'))
    issues=[]
